package com.portfolio.catalogservice.domain; import jakarta.persistence.*; import java.math.BigDecimal; @Entity public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; private String description; private BigDecimal price; private String sku; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public String getSku(){return sku;} public void setSku(String v){sku=v;} }